import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";import"./chunks/assets.B5FjAcX4.js";var i=JSON.parse(`{"title":"svn使用详解","description":"","frontmatter":{},"headers":[],"relativePath":"version-control/svn/usage.md","filePath":"version-control/svn/usage.md"}`),a={name:`version-control/svn/usage.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="svn使用详解" tabindex="-1">svn使用详解 <a class="header-anchor" href="#svn使用详解" aria-label="Permalink to “svn使用详解”">​</a></h1><h2 id="checkout-检出操作" tabindex="-1">（Checkout）检出操作 <a class="header-anchor" href="#checkout-检出操作" aria-label="Permalink to “（Checkout）检出操作”">​</a></h2><ul><li><p>链接到SVN服务器端<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-1.C_YCi2Ob.png" alt="" width="769" height="573"></p></li><li><p>拉取服务端数据到本地<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-2.BiWcl2vs.png" alt="" width="478" height="164"><br> 注意：Checkout只在第一次链接时操作一次，以后如果进行更新操作请使用Update（更新指令）</p></li></ul><h2 id="commit-提交操作" tabindex="-1">（Commit）提交操作 <a class="header-anchor" href="#commit-提交操作" aria-label="Permalink to “（Commit）提交操作”">​</a></h2><p>将本地修改的代码提交到远程<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-3.CE6NHMHA.png" alt="" width="492" height="196"><br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-4.Bzb7eGFa.png" alt="" width="620" height="522"><br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-5.Y0ytduNM.png" alt="" width="664" height="308"></p><h2 id="update更新操作" tabindex="-1">（Update更新操作） <a class="header-anchor" href="#update更新操作" aria-label="Permalink to “（Update更新操作）”">​</a></h2><p>将远程修改的代码更新到本地<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-6.B_HuWTGN.png" alt="" width="494" height="145"></p><h2 id="忽略功能" tabindex="-1">忽略功能 <a class="header-anchor" href="#忽略功能" aria-label="Permalink to “忽略功能”">​</a></h2><p>有些文件不希望上传至svn服务器，应该将该文件或该类型的文件添加至忽略列表</p><ol><li><p>忽略某个指定的文件<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-7.GaNMZa5N.png" alt="" width="717" height="191"></p></li><li><p>忽略某类型文件<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-8.BtEK3YBo.png" alt="" width="675" height="170"></p></li></ol><h2 id="版本回退" tabindex="-1">版本回退 <a class="header-anchor" href="#版本回退" aria-label="Permalink to “版本回退”">​</a></h2><p>有些时候，软件的运行可能使开发者或使用者不满意，这时我们需要把当前版本退回到以前的某个版本。</p><ol><li><p>在项目空白处鼠标右键，采用如下图所示操作<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-9.B9OHf2Ow.png" alt="" width="718" height="437"></p></li><li><p>根据日志或者版本号进行版本回退<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-10.DKDDWLza.png" alt="" width="381" height="316"></p></li><li><p>根据日志信息选择要回退的状态，点击确定即可<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-11.B3Tf8GUZ.png" alt="" width="649" height="567"></p></li></ol><h2 id="版本冲突" tabindex="-1">版本冲突 <a class="header-anchor" href="#版本冲突" aria-label="Permalink to “版本冲突”">​</a></h2><p>在实际项目开发中，如果两个人同时修改某个文件就会产生版本冲突问题。</p><p>点击commit的时候发现如下错误，有冲突，禁止提交<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-12.B9BBQYx4.png" alt="" width="663" height="303"></p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to “解决方案”">​</a></h3><ol><li>update远程代码到本地<br><img src="/blog-notes/assets/svn%E4%BD%BF%E7%94%A8%E8%AF%A6%E8%A7%A3-13.CikvtZHA.png" alt="" width="626" height="86"></li></ol><ul><li><p>index.php ：整合后的index.php冲突文件</p></li><li><p>index.php.mine ：本地修改后的index.php文件</p></li><li><p>index.php.r6 ：index.php的起始文件（最初的）</p></li><li><p>index.php.r7 ：另外一位同事修改后的index.php文件</p></li></ul><ol start="2"><li>删除其他index.php文件，只保留整合后的index.php</li></ol><ul><li><p>打开index.php文件，手动将冲突解决</p></li><li><p>解决之后重新commit即可</p></li></ul>`,21)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};